# fish completion for demo — generated by `demo completion fish`
function __demo_at
    set -l words (commandline -opc)
    set -e words[1]
    set -l cmdpath
    set -l skip 0
    for word in $words
        if test $skip = 1
            set skip 0
            continue
        end
        switch $word
            case --data-dir --account -a --site -s --limit -n --param -p --method --url --before
                set skip 1
            case '-*'
            case '*'
                set -a cmdpath $word
        end
    end
    test "$cmdpath" = "$argv"
end
complete -c demo -f
complete -c demo -n '__demo_at' -a 'session' -d 'Sessions'
